using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpStdioServer.Tools;

[McpServerToolType]
public sealed class FetchPostTool
{
    [McpServerTool("fetch_post"), Description("Fetches a post by ID from the external API.")]
    public static async Task<string> FetchPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric ID of the post to fetch (1-100).")] int postId,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        var post = await client.GetFromJsonAsync<Post>(
            $"/posts/{postId}", cancellationToken);

        if (post is null)
            return $"No post found with ID {postId}.";

        return $"""
            Post #{post.Id}
            Title: {post.Title}
            Body:  {post.Body}
            """;
    }

    private sealed class Post
    {
        [JsonPropertyName("id")]    public int Id { get; set; }
        [JsonPropertyName("title")] public string Title { get; set; } = "";
        [JsonPropertyName("body")]  public string Body { get; set; } = "";
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpStdioServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a summarization prompt for the given text.")]
    public static IList<ChatMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional target style: brief, detailed, or bullet-points.")] string? style = "brief")
    {
        var systemMsg = style switch
        {
            "detailed"      => "You are an expert summarizer. Produce a thorough summary that preserves key details.",
            "bullet-points" => "You are an expert summarizer. Produce a concise bullet-point summary.",
            _               => "You are an expert summarizer. Produce a brief, one-paragraph summary.",
        };

        return
        [
            new ChatMessage(ChatRole.System, systemMsg),
            new ChatMessage(ChatRole.User, $"Please summarize the following text:\n\n{text}"),
        ];
    }
}

// Minimal ChatMessage/ChatRole types expected by the MCP prompt contract.
public enum ChatRole { System, User, Assistant }

public sealed class ChatMessage(ChatRole role, string content)
{
    public ChatRole Role { get; } = role;
    public string Content { get; } = content;
}

